.box {
  width: var(--box-width, red);
  height: 100px;
  background: blue;
}

.overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.overlay button {
  pointer-events: auto;
}

.card {
  position: relative;
  overflow: hidden;
  height: 200px;
}

.card .badge {
  position: absolute;
  top: -10px;
  right: -10px;
}

.card {
  transition: all 0.3s ease;
  background: white;
  transform: scale(1);
}
